	this.tBlur2.setTransform(-574.55,177.85,1.2668,1.1819);

	this.tBlur1 = new cjs.Text("The cranial nerves III, IV and VI provide motor response to sensory inputs through the optic nerve (CN II). The motor nerves account for the movement of the eye along the antero-posterior axis of the eyeball. The extraoccular skeletal muscles dorsal rectus (DR) and ventral rectus (VR) allow the dorsal to ventral movement of the eye while the medial rectus (MR) and lateral rectus (LR) muscles account for the  latero-medial movements. The rotation of the eyeball along the equator is controlled by the dorsal oblique (DO) and ventral oblique (VO) muscles. In animals, the retraction of the eye into the socket is activated by the retractor bulbi muscle. The lateral rectus and the retractor bulbi are innervated by CN VI (abduscent), the medial, dorsal, ventral rectus muscles and the ventral oblique are innervated by CNIII (oculomotor nerve) while the dorsal rectus is innervated by CN IV (trochlea nerve). The nuclei of CNIII and IV are in the midbrain while that of CN VI is in the hindbrain. ", "16px 'Arial'");
	this.tBlur1.name = "tBlur1";
	this.tBlur1.lineHeight = 20;
	this.tBlur1.lineWidth = 867;
	this.tBlur1.parent = this;
