		// set coordinates for pupil movement
		function fResetPupils() {
		
			// set left pupil default range of movement
			vLeftPupilLeft = vLeftPupilLeftDefault;
			vLeftPupilRight = vLeftPupilRightDefault;
			vLeftPupilUpLeft = vLeftPupilUpLeftDefault;
			vLeftPupilDownLeft = vLeftPupilDownLeftDefault;
			vLeftPupilUpRight = vLeftPupilUpRightDefault;
			vLeftPupilDownRight = vLeftPupilDownRightDefault;
		
			// set right pupil default range of movement
			vRightPupilRight = vRightPupilRightDefault;
			vRightPupilLeft = vRightPupilLeftDefault;
			vRightPupilUpLeft = vRightPupilUpLeftDefault;
			vRightPupilDownLeft = vRightPupilDownLeftDefault;
			vRightPupilUpRight = vRightPupilUpRightDefault;
			vRightPupilDownRight = vRightPupilDownRightDefault;
			
			// set pupil positions
			root.rightPupil_mc.x = vRightPupilCentreX;
			root.rightPupil_mc.y = vPupilCentreY;
			
			root.leftPupil_mc.x = vLeftPupilCentreX;
			root.leftPupil_mc.y = vPupilCentreY;
			
		}
		
		
