		function fChangeDog() {
			console.log("change dog colour");
			
			// record previous colour
			vPreviousDogMovie = vDogMovie;
		
			// generate dog colour (repeat if it is the same as last time)
			do {
				fSetRandomColour();
				} while (vDogMovie == vPreviousDogMovie);
		
		
			// hide all dog movies
			fHideDogs();
			
			// make current colour visible
			root[vDogMovie].visible = true;
			
			
		
		}
		
		
		function fSetRandomColour() {
		
			// randomly allocate a dog colour
			vDogNumber = fRandomNumber(0, 4);
		
			switch (vDogNumber) {
				case 0:
					vDogMovie = "dog_mc";
					break;
				case 1:
					vDogMovie = "black_dog_mc";
					break;
				case 2:
					vDogMovie = "red_dog_mc";
					break;
				case 3:
					vDogMovie = "chocolate_dog_mc";
					break;
			}
		
			root.tDog.text = vDogMovie;
		}
		
		
		
