		function fClearRollovers() {
			// set all the buttons to default colour
			root.buttons_mc.condition1_btn.gotoAndStop("Up");	
			root.buttons_mc.condition2_btn.gotoAndStop("Up");
			root.buttons_mc.condition3_btn.gotoAndStop("Up");	
			root.buttons_mc.condition4_btn.gotoAndStop("Up");	
			root.buttons_mc.condition5_btn.gotoAndStop("Up");
			root.buttons_mc.condition6_btn.gotoAndStop("Up");
			root.buttons_mc.condition7_btn.gotoAndStop("Up");
			root.buttons_mc.condition8_btn.gotoAndStop("Up");
			
			// set new patient button to default colour
			root.newPatient_btn.gotoAndStop("Up");
			
			//set toggle button to default colour
			fResetToggle();
		}
		
		
		
		function fResetMCQ() {
		
			// set all the buttons to default state
			fClearRollovers();
			
			// reset question to unanswered
			vMCQResult = "Unanswered";
			root.tMCQ.text = vMCQResult;
			
			// hide feedback
			root.tFeedback.text = "";
			
			
		}
		
		function fSetRollover() {
			// show a tick or cross in DIAGNOSE mode unless unanswered
			if (vMode == "diagnose") {
				
				// if answer is correct show tick next to checked button
				if (vMCQResult == "Correct") {
					root.buttons_mc[vButtonChecked].gotoAndStop("Correct");
				}
		
				// if answer is wrong show cross next to checked button
				else if (vMCQResult == "Incorrect") {
					root.buttons_mc[vButtonChecked].gotoAndStop("Incorrect");
				}
			}
			
			// don't show a tick or cross in LEARN mode
			else {
				root.buttons_mc[vButtonChecked].gotoAndStop("Over");
			}	
		
		}
		
		
		
		function fQuizButtonOver(e) {
			
			// set all the buttons to default colour
			fClearRollovers();
			
			// set the current button to rollover colour
			e.currentTarget.gotoAndStop("Over");
			
			// highlight selected button
			fSetRollover();
		}
		
		function fQuizButtonOut(e) {
			
			// set all the buttons to default colour
			fClearRollovers();
			
			// highlight selected button
			fSetRollover();
			
			// show tick or cross;
			fSetRollover();
			
		}
		
		function fQuizButtonDown(e) {
			
			// set the current button to rollover colour
			e.currentTarget.gotoAndStop("Down");
			
		}
		
		
