		// FINGER FUNCTIONS
		
		this.finger_btn.on("pressup", function (e) {
			
			// set finger back to centre
			root.finger_btn.x = vFingerX + vFingerOffsetX;
			root.finger_btn.y = vFingerY + vFingerOffsetY;
			
			// set pupil positions back to normal
			root.rightPupil_mc.x = vRightPupilCentreX;
			root.rightPupil_mc.y = vPupilCentreY;
			
			root.leftPupil_mc.x = vLeftPupilCentreX;
			root.leftPupil_mc.y = vPupilCentreY;
			
			// enable screen dragging on mobile devices
			//root.stage.preventSelection = false;
			
		});
		
		this.finger_btn.on("pressmove", function (e) {
		
			// don't move background along with finger
			e.nativeEvent.preventDefault(); 
			
			
			var vDragLocation = stage.globalToLocal(e.stageX, e.stageY)
			e.currentTarget.x = vDragLocation.x;
			e.currentTarget.y = vDragLocation.y;
		
			
			
			// FINGER TO DOG's LEFT of the H shape
			if (vDragLocation.x >= vHLeftX) {
		
				// move pupils towards dog's left
				root.rightPupil_mc.x = vRightPupilLeft;
				root.leftPupil_mc.x = vLeftPupilLeft;
		
				// move finger to dog's left side of H shape
				root.finger_btn.x = vHLeftX + vFingerOffsetX;
		
				// if finger to dog's left of H shape and above H shape
				if (vDragLocation.y <= vHTopY) {
		
					// snap finger to top
					root.finger_btn.y = (vHTopY + vFingerOffsetY);
		
					// move pupils up 
					root.rightPupil_mc.y = vRightPupilUpLeft;
					root.leftPupil_mc.y = vLeftPupilUpLeft;
				}
		
				// if finger to dog's left of H shape and below H shape
				else if (vDragLocation.y >= vHBottomY) {
					// snap finger to bottom
					root.finger_btn.y = vHBottomY + vFingerOffsetY;
		
					// move pupils down 
					root.rightPupil_mc.y = vRightPupilDownLeft;
					root.leftPupil_mc.y = vLeftPupilDownLeft;
				}
		
				// else finger to dog's left of H shape and alongside H shape
				else {
					//match the vertical position of cursor to finger
					root.finger_btn.y = (vDragLocation.y + vFingerOffsetY);
		
					// move pupils
					// pupil movement = starting point + ( movement of finger / rate pupil moves when finger moves )
					// pupil movement = starting point + ( movement of finger / (range of finger movement / range of pupil movement) )
		
					// make sure pupils are looking towards dog's left
					root.rightPupil_mc.x = vRightPupilLeft;
					root.leftPupil_mc.x = vLeftPupilLeft;
		
					// pupils moving up on dog's left
					if (root.finger_btn.y <= vHMiddleY) {
						root.rightPupil_mc.y = vHMiddleY - ((vHMiddleY - root.finger_btn.y) / ((vHMiddleY - vHTopY) / (vPupilCentreY - vRightPupilUpLeft)));
						root.leftPupil_mc.y = vHMiddleY - ((vHMiddleY - root.finger_btn.y) / ((vHMiddleY - vHTopY) / (vPupilCentreY - vLeftPupilUpLeft)));
		
						// pupils moving down on dog's left
					} else {
						root.rightPupil_mc.y = vHMiddleY + ((root.finger_btn.y - vHMiddleY) / ((vHBottomY - vPupilCentreY) / (vRightPupilDownLeft - vPupilCentreY)));
						root.leftPupil_mc.y = vHMiddleY + ((root.finger_btn.y - vHMiddleY) / ((vHBottomY - vPupilCentreY) / (vLeftPupilDownLeft - vPupilCentreY)));
							}
				}
		
			}
		
			// FINGER TO DOG's RIGHT of the H shape
			else if (vDragLocation.x <= vHRightX) {
		
				// move pupils towards dog's right
				root.rightPupil_mc.x = vRightPupilRight;
				root.leftPupil_mc.x = vLeftPupilRight;
				
				// move finger to dog's right side of H shape
				root.finger_btn.x = vHRightX + vFingerOffsetX;
				
				// finger to dog's right and above H
				if (vDragLocation.y <= vHTopY) {
							
					// move finger to top
					root.finger_btn.y = vHTopY+vFingerOffsetY;
		
					// move pupils up 
					root.rightPupil_mc.y = vRightPupilUpRight;
					root.leftPupil_mc.y = vLeftPupilUpRight;		
				}
			
				// finger to dog's right and below H 
				else if (vDragLocation.y >= vHBottomY) {
		
					// move finger to bottom
					root.finger_btn.y = vHBottomY + vFingerOffsetY;
		
					// move pupils down 
					root.rightPupil_mc.y = vRightPupilDownRight;
					root.leftPupil_mc.y = vLeftPupilDownRight;				
				} 
				
				// finger to dog's right and alongside H
				else {
		
					// move finger to dog's right
					root.finger_btn.y = (vDragLocation.y + vFingerOffsetY);
		
					// pupils moving up on dog's right
					if (root.finger_btn.y <= vHMiddleY) {
						root.rightPupil_mc.y = vHMiddleY - ((vHMiddleY - root.finger_btn.y)/ ((vHMiddleY-vHTopY)/(vPupilCentreY-vRightPupilUpRight)));
						root.leftPupil_mc.y = vHMiddleY - ((vHMiddleY - root.finger_btn.y)/ ((vHMiddleY-vHTopY)/(vPupilCentreY-vLeftPupilUpRight)));
					}
		
					// pupils moving down on dog's right
					else {
						root.rightPupil_mc.y = vHMiddleY + ((root.finger_btn.y - vHMiddleY)/ ((vHBottomY-vPupilCentreY)/(vRightPupilDownRight-vPupilCentreY)));
						root.leftPupil_mc.y = vHMiddleY + ((root.finger_btn.y - vHMiddleY)/ ((vHBottomY-vPupilCentreY)/(vLeftPupilDownRight-vPupilCentreY)));
					}
		
				}	
			}
			
		
		
			// FINGER WITHIN H SHAPE (not to the left or right)
			else {
				// animate finger
				root.finger_btn.y = (vHMiddleY + vFingerOffsetY);
				root.finger_btn.x = (vDragLocation.x + vFingerOffsetX);
		
				// put pupils back if they're looking up or down
				root.rightPupil_mc.y = vPupilCentreY;
				root.leftPupil_mc.y = vPupilCentreY;
		
				//move eyes left and right
		
				// pupils move horizontally from centre to right and back
				if (vDragLocation.x < vHMiddleX) {
					root.leftPupil_mc.x = vLeftPupilRight + ((vDragLocation.x-vHRightX)/((vHMiddleX-vHRightX)/(vLeftPupilCentreX-vLeftPupilRight)));
					root.rightPupil_mc.x = vRightPupilRight + ((vDragLocation.x-vHRightX)/((vHMiddleX-vHRightX)/(vRightPupilCentreX-vRightPupilRight)));
		
				// pupils moves horizontally from centre to left and back
				} else {
					root.leftPupil_mc.x = vLeftPupilCentreX + ((vDragLocation.x-vHMiddleX)/((vHLeftX-vHMiddleX)/(vLeftPupilLeft-vLeftPupilCentreX)));
					root.rightPupil_mc.x = vRightPupilCentreX + ((vDragLocation.x-vHMiddleX)/((vHLeftX-vHMiddleX)/(vRightPupilLeft-vRightPupilCentreX)));
				}
			
			}
		
		});
		
		
		
		
