		// initialise new patient
			function fResetDogEyes() {
				console.log("in function resetdogeyes");
				console.log("vCondition: ");
				console.log(vCondition);
				console.log();
				console.log("vTool: ");
				console.log(vTool);
		
		
				// put eyes back to centre and set default movement
				fResetPupils();
			
		
				if (vTool == "Torch") {
					console.log("reseteyes code thinks tool is Torch. Set initial appearance for condition");
					switch (vCondition) {
		
						// set appearance
		
						case "No deficit":
							console.log("normal eyelids and pupils");
							fOpenLeftEye();
							fOpenRightEye();
							fLeftPupilNormal();
							fRightPupilNormal();
							break;
						case "CN II deficit left":
							console.log("normal eyelids and pupils");
							fOpenLeftEye();
							fOpenRightEye();
							fLeftPupilNormal();
							fRightPupilNormal();
							break;
						case "CN II deficit right":
							console.log("normal eyelids and pupils");
							fOpenLeftEye();
							fOpenRightEye();
							fLeftPupilNormal();
							fRightPupilNormal();
							break;
						case "CN III deficit right":
							console.log("CN III deficit right - droop right eye, dilate right pupil");
							fDroopRightEye();
							fOpenLeftEye();
							fLeftPupilNormal();
							fRightPupilDilate();
							break;
						case "CN III deficit left":
							console.log("CN III deficit left - droop left eye, dilate left pupil");
							fDroopLeftEye();
							fOpenRightEye();
							fLeftPupilDilate();
							fRightPupilNormal();
							break;
						case "Horner's left":
							console.log("Horner's left - droop left eye, contract left pupil");
							fDroopLeftEye();
							fOpenRightEye();
							fLeftPupilContract();
							fRightPupilNormal();
							break;
						case "Horner's right":
							console.log("Horner's right - droop right eye, contract right pupil");
							fDroopRightEye();
							fOpenLeftEye();
							fRightPupilContract();
							fLeftPupilNormal();
							break;
					}
				} else if (vTool == "Finger") {
		
					// set appearance
					console.log("reseteyes code thinks tool is Finger. Set initial appearance for condition");
		
					switch (vCondition) {
						case "No deficit":
							fOpenLeftEye();
							fOpenRightEye();
							fLeftPupilNormal();
							fRightPupilNormal();
							break;
						case "Dorsal rectus deficit":
							fOpenLeftEye();
							fOpenRightEye();
							fLeftPupilNormal();
							fRightPupilNormal();
							break;
						case "Medial rectus deficit":
							fOpenLeftEye();
							fOpenRightEye();
							fLeftPupilNormal();
							fRightPupilNormal();
							break;
						case "Ventral rectus deficit":
							fOpenLeftEye();
							fOpenRightEye();
							fLeftPupilNormal();
							fRightPupilNormal();
							break;
						case "Ventral oblique deficit":
							fOpenLeftEye();
							fOpenRightEye();
							fLeftPupilNormal();
							fRightPupilNormal();
							break;
						case "Lateral rectus or CN VI deficit":
							fOpenLeftEye();
							fOpenRightEye();
							fLeftPupilNormal();
							fRightPupilNormal();
							break;
						case "Dorsal oblique or CN IV deficit":
							fOpenLeftEye();
							fOpenRightEye();
							fLeftPupilNormal();
							fRightPupilNormal();
							break;
						case "CN III deficit":
							console.log("set correct appearance for CN III deficit");
							if (vEye == "Right") {
								fOpenLeftEye();
								fDroopRightEye();
								fLeftPupilNormal();
								fRightPupilDilate();
							}
							else {
								fOpenRightEye();
								fDroopLeftEye();
								fRightPupilNormal();
								fLeftPupilDilate();
							}
							
							break;
					}
		
					// set pupil movement
					console.log("set pupil movement depending on deficit");
					
					// deficit in right eye
					if (vEye == "Right") {
						switch (vCondition) {
							case "No deficit" :
								// do nothing
								break;
							case "Dorsal rectus deficit" :
								// right pupil doesn't move up on ear side
								vRightPupilUpRight=vPupilCentreY;
								break;
							case "Medial rectus deficit" :
								// right pupil doesn't move from centre towards nose
								vRightPupilLeft=vRightPupilCentreX;
								break;
							case "Ventral rectus deficit" :
								// right pupil doesn't move down on ear side
								vRightPupilDownRight=vPupilCentreY;
								break;
							case "Ventral oblique deficit" :
								// right pupil doesn't move up on nose side
								vRightPupilUpLeft=vPupilCentreY;
								break;
							case "Lateral rectus or CN VI deficit" :
								// right pupil doesn't move from centre towards ear
								vRightPupilRight=vRightPupilCentreX;
								break;
							case "Dorsal oblique or CN IV deficit" :
								// right pupil doesn't move down on nose side
								vRightPupilDownLeft=vPupilCentreY;
								break;				
							case "CN III deficit" :
								// right pupil only moves from centre towards ear
								vRightPupilLeft=vRightPupilCentreX;
								vRightPupilUpLeft=vPupilCentreY;
								vRightPupilDownLeft=vPupilCentreY;
								vRightPupilUpRight=vPupilCentreY;
								vRightPupilDownRight=vPupilCentreY;
								break;
						}
					}
					// deficit in left eye
					else {
						switch (vCondition) {
							case "No deficit" :
								// do nothing
								break;
							case "Dorsal rectus deficit" :
								// left pupil doesn't move up on ear side
								vLeftPupilUpLeft=vPupilCentreY;
								break;
							case "Medial rectus deficit" :
								// left pupil doesn't move from centre towards nose
								vLeftPupilRight=vLeftPupilCentreX;
								break;
							case "Ventral rectus deficit" :
								// left pupil doesn't move down on ear side
								vLeftPupilDownLeft=vPupilCentreY;
								break;
							case "Ventral oblique deficit" :
								// left pupil doesn't move up on nose side
								vLeftPupilUpRight=vPupilCentreY;
								break;
							case "Lateral rectus or CN VI deficit" :
								// left pupil doesn't move from centre towards ear
								vLeftPupilLeft=vLeftPupilCentreX;
								break;
							case "Dorsal oblique or CN IV deficit" :
								// left pupil doesn't move down on nose side
								vLeftPupilDownRight=vPupilCentreY;
								break;				
							case "CN III deficit" :
								// left pupil only moves from centre towards ear
								vLeftPupilRight=vLeftPupilCentreX;
								vLeftPupilUpRight=vPupilCentreY;
								vLeftPupilDownRight=vPupilCentreY;
								vLeftPupilUpLeft=vPupilCentreY;
								vLeftPupilDownLeft=vPupilCentreY;
								break;
						}
					}
				
		
		
				} else if (vTool == "Swab") {
					console.log("reseteyes code thinks tool is Swab");
					switch (vCondition) {
						case "No deficit":
							fOpenLeftEye();
							fOpenRightEye();
							fLeftPupilNormal();
							fRightPupilNormal();
							break;
						case "CN V1 deficit left":
							fOpenLeftEye();
							fOpenRightEye();
							fLeftPupilNormal();
							fRightPupilNormal();
							break;
						case "CN V1 deficit right":
							fOpenLeftEye();
							fOpenRightEye();
							fLeftPupilNormal();
							fRightPupilNormal();
							break;
						case "CN VII left eye paralysis":
							fParalyseLeftEye();
							fOpenRightEye();
							fLeftPupilNormal();
							fRightPupilNormal();
							break;
						case "CN VII right eye paralysis":
							fOpenLeftEye();
							fParalyseRightEye();
							fLeftPupilNormal();
							fRightPupilNormal();
							break;
					}
				}
			}
		
		
		
